//! One completed source-bound FIX operation, over its actual exhausted raw-source roster.
use crate::selected_exclusions_wire::{Frame,Seal,MAX_STREAM};use serde::{Deserialize,Serialize};use std::{io,path::Path};
#[derive(Clone,Copy,Debug,Serialize,Deserialize,Eq,PartialEq,Ord,PartialOrd,Hash)]pub enum Mode{#[serde(rename="tracked-list-macros")]TrackedListMacros,#[serde(rename="tracked")]Tracked,#[serde(rename="tracked-tests")]TrackedTests,#[serde(rename="tracked-drop-declared")]TrackedDropDeclared}
fn presence<'de,D:serde::Deserializer<'de>>(d:D)->Result<Option<Seal>,D::Error>{Option::<Seal>::deserialize(d)}
#[derive(Clone,Copy,Debug,Deserialize,Serialize,Eq,PartialEq)]pub enum Schema{#[serde(rename="native-authored-fix-batch-v1")]V1}
#[derive(Clone,Copy,Debug,Deserialize,Serialize,Eq,PartialEq)]pub enum Scope{#[serde(rename="all_tracked_sources")]AllTrackedSources,#[serde(rename="path_prefixes")]PathPrefixes}
#[derive(Clone,Debug,Deserialize,Serialize)]#[serde(deny_unknown_fields)]pub struct Terminal{pub schema:Schema,pub complete:bool,pub full_policy_parity:bool,pub root:std::path::PathBuf,pub scope:Scope,pub prefixes:Vec<String>,pub mode:Mode,pub apply:bool,pub frame:Frame,pub selected:u64,pub visited:u64,pub rewrites:u64,pub residue:u64,pub committed_files:u64,#[serde(deserialize_with="presence")]pub diagnostics:Option<Seal>,pub report:Seal}
impl Terminal{pub fn require(&self,root:&Path,prefixes:&[String],mode:Mode,apply:bool)->io::Result<()>{
 let scope=if prefixes.is_empty(){Scope::AllTrackedSources}else{Scope::PathPrefixes};
 if !self.complete||self.full_policy_parity||!self.root.is_absolute()||self.root!=root||self.prefixes.as_slice()!=prefixes||self.scope!=scope||self.mode!=mode||self.apply!=apply||self.visited!=self.selected||self.committed_files>self.visited||self.committed_files>self.rewrites||(!apply&&self.committed_files!=0)||(apply&&(self.rewrites!=0)!=(self.committed_files!=0))||self.report.length==0||self.report.length>MAX_STREAM||self.diagnostics.as_ref().is_some_and(|s|s.length==0||s.length>MAX_STREAM)||self.report.length.checked_add(self.diagnostics.as_ref().map_or(0,|s|s.length)).is_none_or(|n|n>MAX_STREAM){return Err(io::Error::new(io::ErrorKind::InvalidData,"native FIX batch terminal differs from actual exhausted scope/request/commit"))}Ok(())
}}

#[cfg(test)]mod tests{use super::*;use crate::selected_exclusions_wire::Hex128;
 #[test]fn fix_terminal_requires_actual_exhausted_all_or_prefix_scope_and_exact_commit_counts(){
 let root=if cfg!(windows){Path::new("E:/actual-project")}else{Path::new("/actual-project")};let mut t=Terminal{schema:Schema::V1,complete:true,full_policy_parity:false,root:root.into(),scope:Scope::AllTrackedSources,prefixes:Vec::new(),mode:Mode::Tracked,apply:true,frame:Frame{semantic_revision:Hex128(1),source_revision:Hex128(2),policy_revision:Hex128(3)},selected:3,visited:3,rewrites:2,residue:0,committed_files:2,diagnostics:None,report:Seal{length:1,hash:Hex128(4)}};t.require(root,&[],Mode::Tracked,true).unwrap();t.visited=2;assert!(t.require(root,&[],Mode::Tracked,true).is_err());t.visited=3;t.committed_files=3;assert!(t.require(root,&[],Mode::Tracked,true).is_err());t.committed_files=2;assert!(t.require(root,&[],Mode::Tracked,false).is_err());assert!(t.require(root,&[],Mode::TrackedTests,true).is_err());t.prefixes=vec!["code/path".into()];assert!(t.require(root,&t.prefixes,Mode::Tracked,true).is_err());t.scope=Scope::PathPrefixes;t.require(root,&t.prefixes,Mode::Tracked,true).unwrap();assert!(t.require(root,&[],Mode::Tracked,true).is_err());t.diagnostics=Some(Seal{length:MAX_STREAM,hash:Hex128(5)});assert!(t.require(root,&t.prefixes,Mode::Tracked,true).is_err());let mut data=serde_json::to_value(t).unwrap();data.as_object_mut().unwrap().remove("visited");assert!(serde_json::from_value::<Terminal>(data).is_err());
 }
}
